const assert=require('node:assert/strict');
const P=require('../engines/training-prescription-policy.js');
const RT=require('../engines/race-target-intent.js');
const shorthand=RT.resolve({kind:'set',raw:'50 #1 @100p @ 1:30',text:'50 #1 @100p @ 1:30',distance:50,cycleSeconds:90});
assert.equal(shorthand.raceIntent.distance,100,'@100p must create a 100 race-pace target intent');
assert.equal(shorthand.raceTargetIntent.workDistance,50,'shorthand must preserve the delivered 50m work distance');
const rp200={raw:'6 x 25 #1 Stroke @ 1:00 · #2-6 @ 200 Race Pace',distance:25,cycleSeconds:60,raceIntent:{distance:200}};
let x=P.safeCycle({item:rp200,targetSeconds:63,referenceWorkSeconds:32});
assert.equal(x.owner,'race-pace');assert.ok(x.cycleSeconds>=95,'63s 200-pace target needs ~30s+ recovery');
const rp100={raw:'4 x 50 #1 Stroke @ 2:30 · #2-4 @ 100 Race Pace',distance:50,cycleSeconds:150,raceIntent:{distance:100}};
x=P.safeCycle({item:rp100,targetSeconds:55,referenceWorkSeconds:30});
assert.equal(x.owner,'race-pace');assert.equal(x.cycleSeconds,150,'safe policy must never shorten an already-longer coach-authored 2:30 cycle');assert.ok(x.restSeconds>=95,'authored 2:30 must remain the delivered recovery');
const rp100Unsafe={raw:'6 x 25 #1 Stroke @ 1:00 · #2-6 @ 100 Race Pace',distance:25,cycleSeconds:60,raceIntent:{distance:100}};
x=P.safeCycle({item:rp100Unsafe,targetSeconds:29,referenceWorkSeconds:15});assert.ok(x.cycleSeconds>=90&&x.cycleSeconds<=120,`unsafe 1:00 should lengthen into the comparable 1:30-2:00 range, got ${x.cycleSeconds}`);
const aero={raw:'8 x 100 Freestyle Threshold · 10 seconds rest',distance:100,zone:'Threshold',restSeconds:10};
x=P.safeCycle({item:aero,targetSeconds:72});assert.equal(x.owner,'aerobic');assert.equal(x.restSeconds,10);assert.equal(x.cycleSeconds,85);
const md={full_name:'McKenzie Drage'};assert.equal(P.kickCycleSeconds({raw:'5 x 50 Kick @ 1:00',distance:50,cycleSeconds:60},md,2/3),60,'kick timing must never invent a ratio-derived pace floor; that decision belongs to modification.js');assert.equal(P.kickCycleSeconds({raw:'5 x 50 Kick @ 2:00',distance:50,cycleSeconds:120},md,2/3),120,'kick timing must preserve whatever coach-authored cycle modification.js already decided');
console.log('TRAINING_PRESCRIPTION_POLICY_PASS shorthand-100p authored-longer-preserved comparable-race-pace aerobic-rest kick-authored-preserved');
